# Define the set of allowed digits D
D = [0, 1, 2, 8]

# Function to check divisibility by 3
def check_condition(n):
    if n == 0:
        return False # Natural numbers must be >= 1
    return sum(int(d) for d in str(n)) % 3 == 0

# Count numbers with at most 3 digits
count_3_digits = 0
for n in range(1, 1000):
    if all(int(d) in [0, 1, 2, 8] for d in str(n)) and check_condition(n):
        count_3_digits += 1

print(f"Count of valid numbers up to 999 (at most 3 digits): {count_3_digits}")

# Count numbers with exactly 4 digits (1000 to 9999)
count_4_digits = 0
for n in range(1000, 10000):
    if all(int(d) in [0, 1, 2, 8] for d in str(n)) and check_condition(n):
        count_4_digits += 1

print(f"Count of valid numbers with exactly 4 digits: {count_4_digits}")
